function groups(stepIndex, className){
  const wrap = api.el('div', {class:'play'});
  api.STEPS[stepIndex].groups.forEach(function(g){
    const fs = api.el('fieldset');
    if (g.t) fs.append(api.el('legend', {}, g.t));
    else fs.setAttribute('aria-label', question());
    const box = api.el('div', {class: className === 'bubble' ? 'bubbles' : 'fruits'});
    g.o.forEach(function(raw){
      const item = api.asItem(raw);
      const name = item.v === 'cualquiera' ? 'choice' : className;
      box.append(token(stepIndex === 0 ? 'alcohol' : 'fruta', item, name));
    });
    fs.append(box);
    wrap.append(fs);
  });
  return wrap;
}
function alcoholNode(){ return groups(0, 'bubble'); }

