function toggleAlcohol(value){
  const result = api.alcoholVM.toggle(value);
  if (result.status === 'limit'){
    const why = document.getElementById('why');
    if (why){
      why.hidden = false;
      why.textContent = 'Cinco es el tope.';
    }
    return;
  }
  if (result.added) freshKey = 'a:' + value;
  api.moveFocus = false;
  api.persist();
  renderStage();
  focusPick(value);
}
